`timescale 1ns / 1ps
`default_nettype none

// axil_timer: 32-bit down-counting timer with AXI4-Lite subordinate port and
// level interrupt. Implements the microarchitecture spec
// (prj-ada3a9b9d9.microarchitecture.a2) for requirement req-2b2b91a584.
// Open choice TMR-LOAD-END-EDGE: the periodic reload uses the OLD LOAD value.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // State registers (microarchitecture section 2)
    // ------------------------------------------------------------------
    reg                  aw_held_q;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held_q;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    reg                  rvalid_q;
    reg [1:0]            rresp_q;
    reg [31:0]           rdata_q;
    reg                  en_q;
    reg                  ie_q;
    reg                  mode_q;
    reg [31:0]           load_q;
    reg [31:0]           count_q;
    reg                  expired_q;

    // ------------------------------------------------------------------
    // Write path (section 3)
    // ------------------------------------------------------------------
    wire awready     = !aw_held_q && !bvalid_q;
    wire wready      = !w_held_q && !bvalid_q;
    wire aw_fire     = s_axil_awvalid && awready;
    wire w_fire      = s_axil_wvalid && wready;
    wire wr_complete = (aw_fire && (w_fire || w_held_q)) || (w_fire && aw_held_q);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held_q ? w_data_q : s_axil_wdata;
    wire [3:0]            wr_strb = w_held_q ? w_strb_q : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Address decode (section 5)
    // ------------------------------------------------------------------
    wire wr_hi_zero;
    wire rd_hi_zero;

    generate
        if (ADDR_WIDTH > 4) begin : g_hi
            assign wr_hi_zero = ~|wr_addr[ADDR_WIDTH-1:4];
            assign rd_hi_zero = ~|s_axil_araddr[ADDR_WIDTH-1:4];
        end else begin : g_nohi
            assign wr_hi_zero = 1'b1;
            assign rd_hi_zero = 1'b1;
        end
    endgenerate

    wire       wr_mapped = (wr_addr[1:0] == 2'b00) && wr_hi_zero;
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire [1:0] wr_resp   = (!wr_mapped || (wr_idx == 2'd2)) ? RESP_SLVERR : RESP_OKAY;

    // ------------------------------------------------------------------
    // Register write strobes (section 6.1)
    // ------------------------------------------------------------------
    wire       wr_ok      = wr_complete && wr_mapped;
    wire       ctrl_wr    = wr_ok && (wr_idx == 2'd0) && wr_strb[0];
    wire       load_sel   = wr_ok && (wr_idx == 2'd1);
    wire [3:0] load_wr    = {4{load_sel}} & wr_strb;
    wire       status_clr = wr_ok && (wr_idx == 2'd3) && wr_strb[0] && wr_data[0];

    // ------------------------------------------------------------------
    // Read path (section 4)
    // ------------------------------------------------------------------
    wire arready   = !rvalid_q;
    wire ar_fire   = s_axil_arvalid && arready;
    wire rd_mapped = (s_axil_araddr[1:0] == 2'b00) && rd_hi_zero;

    reg [31:0] rd_mux;
    always @(*) begin
        case (s_axil_araddr[3:2])
            2'd0:    rd_mux = {29'd0, mode_q, ie_q, en_q};
            2'd1:    rd_mux = load_q;
            2'd2:    rd_mux = count_q;
            2'd3:    rd_mux = {31'd0, expired_q};
            default: rd_mux = 32'd0;
        endcase
    end

    // ------------------------------------------------------------------
    // Bus next state (sections 3.2, 4.2)
    // ------------------------------------------------------------------
    wire                  aw_held_n = wr_complete ? 1'b0 : (aw_fire ? 1'b1 : aw_held_q);
    wire                  w_held_n  = wr_complete ? 1'b0 : (w_fire ? 1'b1 : w_held_q);
    wire [ADDR_WIDTH-1:0] aw_addr_n = aw_fire ? s_axil_awaddr : aw_addr_q;
    wire [31:0]           w_data_n  = w_fire ? s_axil_wdata : w_data_q;
    wire [3:0]            w_strb_n  = w_fire ? s_axil_wstrb : w_strb_q;
    wire                  bvalid_n  = wr_complete ? 1'b1 :
                                      ((bvalid_q && s_axil_bready) ? 1'b0 : bvalid_q);
    wire [1:0]            bresp_n   = wr_complete ? wr_resp : bresp_q;
    wire                  rvalid_n  = ar_fire ? 1'b1 :
                                      ((rvalid_q && s_axil_rready) ? 1'b0 : rvalid_q);
    wire [31:0]           rdata_n   = ar_fire ? (rd_mapped ? rd_mux : 32'd0) : rdata_q;
    wire [1:0]            rresp_n   = ar_fire ? (rd_mapped ? RESP_OKAY : RESP_SLVERR) : rresp_q;

    // ------------------------------------------------------------------
    // Timer core (section 6)
    // ------------------------------------------------------------------
    wire        end_edge  = en_q && (count_q[31:1] == 31'd0);
    wire [31:0] count_dec = count_q - 32'd1;
    wire [31:0] end_value = mode_q ? load_q : 32'd0;

    reg        en_n;
    reg        ie_n;
    reg        mode_n;
    reg [31:0] count_n;

    always @(*) begin
        en_n    = en_q;
        ie_n    = ie_q;
        mode_n  = mode_q;
        count_n = count_q;
        if (ctrl_wr) begin
            ie_n   = wr_data[1];
            mode_n = wr_data[2];
            if (wr_data[0]) begin
                en_n    = 1'b1;
                count_n = load_q;
            end else begin
                en_n = 1'b0;
                if (end_edge) begin
                    count_n = end_value;
                end else if (en_q) begin
                    count_n = count_dec;
                end else begin
                    count_n = count_q;
                end
            end
        end else if (end_edge) begin
            if (mode_q) begin
                en_n    = 1'b1;
                count_n = load_q;
            end else begin
                en_n    = 1'b0;
                count_n = 32'd0;
            end
        end else if (en_q) begin
            count_n = count_dec;
        end
    end

    wire [31:0] load_n = {
        load_wr[3] ? wr_data[31:24] : load_q[31:24],
        load_wr[2] ? wr_data[23:16] : load_q[23:16],
        load_wr[1] ? wr_data[15:8]  : load_q[15:8],
        load_wr[0] ? wr_data[7:0]   : load_q[7:0]
    };

    wire expired_n = end_edge ? 1'b1 : (status_clr ? 1'b0 : expired_q);

    // ------------------------------------------------------------------
    // Register block: synchronous active-low reset, then q <= n
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held_q <= 1'b0;
            aw_addr_q <= {ADDR_WIDTH{1'b0}};
            w_held_q  <= 1'b0;
            w_data_q  <= 32'd0;
            w_strb_q  <= 4'd0;
            bvalid_q  <= 1'b0;
            bresp_q   <= 2'b00;
            rvalid_q  <= 1'b0;
            rresp_q   <= 2'b00;
            rdata_q   <= 32'd0;
            en_q      <= 1'b0;
            ie_q      <= 1'b0;
            mode_q    <= 1'b0;
            load_q    <= 32'd0;
            count_q   <= 32'd0;
            expired_q <= 1'b0;
        end else begin
            aw_held_q <= aw_held_n;
            aw_addr_q <= aw_addr_n;
            w_held_q  <= w_held_n;
            w_data_q  <= w_data_n;
            w_strb_q  <= w_strb_n;
            bvalid_q  <= bvalid_n;
            bresp_q   <= bresp_n;
            rvalid_q  <= rvalid_n;
            rresp_q   <= rresp_n;
            rdata_q   <= rdata_n;
            en_q      <= en_n;
            ie_q      <= ie_n;
            mode_q    <= mode_n;
            load_q    <= load_n;
            count_q   <= count_n;
            expired_q <= expired_n;
        end
    end

    // ------------------------------------------------------------------
    // Outputs
    // ------------------------------------------------------------------
    assign s_axil_awready = awready;
    assign s_axil_wready  = wready;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_arready = arready;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rdata   = rdata_q;
    assign s_axil_rresp   = rresp_q;
    assign irq            = expired_q && ie_q;

`ifdef FORMAL
    // Design-intent invariants (microarchitecture section 11 (b), (c)).
    always @(*) begin
        assert (!(aw_held_q && w_held_q));
        if (bvalid_q) assert (!awready && !wready);
        if (aw_held_q || w_held_q) assert (!bvalid_q);
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
