`timescale 1ns / 1ps

// Checker core: drives one axil_timer instance at ADDR_WIDTH = AW and checks it.
module axil_timer_tb_core #(
    parameter integer AW = 4
) (
    input  wire        clk,
    output reg         done,
    output reg  [31:0] n_pass,
    output reg  [31:0] n_fail
);
    localparam [1:0] OKAY     = 2'b00;
    localparam [1:0] SLVERR   = 2'b10;
    localparam [7:0] A_CTRL   = 8'h00;
    localparam [7:0] A_LOAD   = 8'h04;
    localparam [7:0] A_COUNT  = 8'h08;
    localparam [7:0] A_STATUS = 8'h0C;

    reg           aresetn;
    reg  [AW-1:0] awaddr;
    reg           awvalid;
    wire          awready;
    reg  [31:0]   wdata;
    reg  [3:0]    wstrb;
    reg           wvalid;
    wire          wready;
    wire [1:0]    bresp;
    wire          bvalid;
    reg           bready;
    reg  [AW-1:0] araddr;
    reg           arvalid;
    wire          arready;
    wire [31:0]   rdata;
    wire [1:0]    rresp;
    wire          rvalid;
    reg           rready;
    wire          irq;

    axil_timer #(.ADDR_WIDTH(AW)) dut (
        .aclk           (clk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid),
        .s_axil_awready (awready),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid),
        .s_axil_wready  (wready),
        .s_axil_bresp   (bresp),
        .s_axil_bvalid  (bvalid),
        .s_axil_bready  (bready),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid),
        .s_axil_arready (arready),
        .s_axil_rdata   (rdata),
        .s_axil_rresp   (rresp),
        .s_axil_rvalid  (rvalid),
        .s_axil_rready  (rready),
        .irq            (irq)
    );

    // Edge counter: after "@(posedge clk); #1;" cyc is the number of the edge just taken.
    integer cyc = 0;
    always @(posedge clk) cyc <= cyc + 1;

    integer    wr_edge;   // completion edge of the last write
    integer    rd_edge;   // accept edge of the last read
    reg [31:0] rd_data;   // data of the last read

    function [AW-1:0] ad;
        input [7:0] a;
        begin
            ad = a[AW-1:0];
        end
    endfunction

    // COUNT after edge x for a count started on edge e0 with LOAD n (running).
    function [31:0] cnt_after;
        input [31:0] n;
        input integer e0;
        input integer x;
        input periodic;
        integer k;
        begin
            k = x - e0;
            if (periodic) begin
                if (n == 32'd0) cnt_after = 32'd0;
                else            cnt_after = n - ($unsigned(k) % n);
            end else begin
                if ($unsigned(k) < n) cnt_after = n - $unsigned(k);
                else                  cnt_after = 32'd0;
            end
        end
    endfunction

    task check;
        input cond;
        input integer id;
        begin
            if (cond) begin
                n_pass = n_pass + 32'd1;
            end else begin
                n_fail = n_fail + 32'd1;
                $error("AW=%0d check %0d failed at edge %0d", AW, id, cyc);
            end
        end
    endtask

    task check_eq;
        input [31:0] got;
        input [31:0] exp;
        input integer id;
        begin
            if (got == exp) begin
                n_pass = n_pass + 32'd1;
            end else begin
                n_fail = n_fail + 32'd1;
                $error("AW=%0d check %0d failed at edge %0d: got 0x%08h expected 0x%08h",
                       AW, id, cyc, got, exp);
            end
        end
    endtask

    task step;
        begin
            @(posedge clk);
            #1;
        end
    endtask

    task wait_until;
        input integer e0;
        begin
            while (cyc < e0) step;
        end
    endtask

    task wait_irq;
        input integer lim;
        begin
            while (!irq && cyc < lim) step;
        end
    endtask

    // Write with AW/W start delays; b_dly < 0 means BREADY already high on completion.
    task axi_write;
        input [7:0]   a;
        input [31:0]  d;
        input [3:0]   s;
        input integer aw_dly;
        input integer w_dly;
        input integer b_dly;
        input [1:0]   exp_resp;
        integer k;
        reg aw_done;
        reg w_done;
        reg aw_acc;
        reg w_acc;
        begin
            k = 0;
            aw_done = 1'b0;
            w_done  = 1'b0;
            bready  = (b_dly < 0);
            check(!bvalid, 900);
            while (!(aw_done && w_done) && k < 64) begin
                awvalid = !aw_done && (k >= aw_dly);
                wvalid  = !w_done && (k >= w_dly);
                awaddr  = ad(a);
                wdata   = d;
                wstrb   = s;
                aw_acc  = awvalid && awready;
                w_acc   = wvalid && wready;
                step;
                if (aw_acc) aw_done = 1'b1;
                if (w_acc)  w_done  = 1'b1;
                k = k + 1;
                if (!(aw_done && w_done)) begin
                    check(!bvalid, 901);
                    if (aw_done) check(!awready, 902);
                    if (w_done)  check(!wready, 903);
                end
            end
            awvalid = 1'b0;
            wvalid  = 1'b0;
            check(aw_done && w_done, 904);
            wr_edge = cyc;
            check(bvalid, 905);
            check_eq({30'd0, bresp}, {30'd0, exp_resp}, 906);
            check(!awready && !wready, 907);
            if (b_dly < 0) begin
                step;
                check(!bvalid, 908);
                bready = 1'b0;
            end else begin
                for (k = 0; k < b_dly; k = k + 1) begin
                    step;
                    check(bvalid, 909);
                    check_eq({30'd0, bresp}, {30'd0, exp_resp}, 910);
                    check(!awready && !wready, 911);
                end
                bready = 1'b1;
                step;
                bready = 1'b0;
                check(!bvalid, 912);
            end
        end
    endtask

    // Read; r_dly < 0 means RREADY already high on the accept edge.
    task axi_read;
        input [7:0]   a;
        input integer r_dly;
        input [1:0]   exp_resp;
        integer k;
        reg ar_done;
        reg ar_acc;
        begin
            k = 0;
            ar_done = 1'b0;
            rready  = (r_dly < 0);
            check(!rvalid, 920);
            while (!ar_done && k < 64) begin
                arvalid = 1'b1;
                araddr  = ad(a);
                ar_acc  = arready;
                step;
                if (ar_acc) ar_done = 1'b1;
                else        check(!rvalid, 921);
                k = k + 1;
            end
            arvalid = 1'b0;
            check(ar_done, 922);
            rd_edge = cyc;
            check(rvalid, 923);
            rd_data = rdata;
            check_eq({30'd0, rresp}, {30'd0, exp_resp}, 924);
            check(!arready, 925);
            if (r_dly < 0) begin
                step;
                check(!rvalid, 926);
                rready = 1'b0;
            end else begin
                for (k = 0; k < r_dly; k = k + 1) begin
                    step;
                    check(rvalid, 927);
                    check_eq(rdata, rd_data, 928);
                    check_eq({30'd0, rresp}, {30'd0, exp_resp}, 929);
                end
                rready = 1'b1;
                step;
                rready = 1'b0;
                check(!rvalid, 930);
            end
        end
    endtask

    task wr;
        input [7:0]  a;
        input [31:0] d;
        input [1:0]  r;
        begin
            axi_write(a, d, 4'hF, 0, 0, 0, r);
        end
    endtask

    task rd;
        input [7:0]   a;
        input [31:0]  exp_d;
        input [1:0]   r;
        input integer id;
        begin
            axi_read(a, 0, r);
            check_eq(rd_data, exp_d, id);
        end
    endtask

    integer    e;
    integer    c;
    reg [31:0] v;

    initial begin
        done    = 1'b0;
        n_pass  = 32'd0;
        n_fail  = 32'd0;
        aresetn = 1'b0;
        awaddr  = {AW{1'b0}};
        awvalid = 1'b0;
        wdata   = 32'd0;
        wstrb   = 4'd0;
        wvalid  = 1'b0;
        bready  = 1'b0;
        araddr  = {AW{1'b0}};
        arvalid = 1'b0;
        rready  = 1'b0;
        wr_edge = 0;
        rd_edge = 0;
        rd_data = 32'd0;
        e = 0;
        c = 0;
        v = 32'd0;

        // ---- Reset ----
        repeat (3) @(posedge clk);
        #1;
        check(!bvalid && !rvalid && !irq, 1);
        check(awready && wready && arready, 2);
        aresetn = 1'b1;

        rd(A_CTRL,   32'd0, OKAY, 10);
        rd(A_LOAD,   32'd0, OKAY, 11);
        rd(A_COUNT,  32'd0, OKAY, 12);
        rd(A_STATUS, 32'd0, OKAY, 13);

        // ---- LOAD and strobes ----
        wr(A_LOAD, 32'h11223344, OKAY);
        rd(A_LOAD, 32'h11223344, OKAY, 20);
        axi_write(A_LOAD, 32'hAABBCCDD, 4'b0101, 0, 0, 0, OKAY);
        rd(A_LOAD, 32'h11BB33DD, OKAY, 21);
        axi_write(A_LOAD, 32'hFFFFFFFF, 4'b0000, 0, 0, 0, OKAY);
        rd(A_LOAD, 32'h11BB33DD, OKAY, 22);
        axi_write(A_LOAD, 32'h000000EE, 4'b0001, 0, 0, 0, OKAY);
        rd(A_LOAD, 32'h11BB33EE, OKAY, 23);
        axi_write(A_LOAD, 32'h99000000, 4'b1000, 0, 0, 0, OKAY);
        rd(A_LOAD, 32'h99BB33EE, OKAY, 24);

        // ---- CTRL ----
        wr(A_CTRL, 32'hFFFFFFFA, OKAY);
        rd(A_CTRL, 32'h00000002, OKAY, 30);
        check(!irq, 31);
        axi_write(A_CTRL, 32'h00000007, 4'b1110, 0, 0, 0, OKAY);
        rd(A_CTRL, 32'h00000002, OKAY, 32);
        rd(A_COUNT, 32'd0, OKAY, 33);
        wr(A_CTRL, 32'd0, OKAY);
        rd(A_CTRL, 32'd0, OKAY, 34);

        // ---- COUNT is read-only ----
        wr(A_COUNT, 32'h00001234, SLVERR);
        rd(A_COUNT, 32'd0, OKAY, 40);

        // ---- Misaligned / non-clearing ----
        wr(8'h05, 32'h00000000, SLVERR);
        rd(A_LOAD, 32'h99BB33EE, OKAY, 50);
        wr(8'h01, 32'h00000007, SLVERR);
        rd(A_CTRL, 32'd0, OKAY, 51);
        wr(8'h0E, 32'h00000001, SLVERR);
        rd(8'h02, 32'd0, SLVERR, 52);
        rd(8'h07, 32'd0, SLVERR, 53);
        rd(8'h0B, 32'd0, SLVERR, 54);
        wr(A_STATUS, 32'd0, OKAY);
        axi_write(A_STATUS, 32'h00000001, 4'b1110, 0, 0, 0, OKAY);
        rd(A_STATUS, 32'd0, OKAY, 55);
        check(!irq, 56);

        // ---- Out of range (wider address only) ----
        if (AW > 4) begin
            wr(8'h14, 32'hDEADBEEF, SLVERR);
            rd(A_LOAD, 32'h99BB33EE, OKAY, 60);
            wr(8'h10, 32'h00000007, SLVERR);
            rd(A_CTRL, 32'd0, OKAY, 61);
            rd(8'h10, 32'd0, SLVERR, 62);
            rd(8'h14, 32'd0, SLVERR, 63);
            rd(8'h1C, 32'd0, SLVERR, 64);
            if (AW > 5) begin
                rd(8'h20, 32'd0, SLVERR, 65);
                wr(8'h24, 32'h12345678, SLVERR);
                rd(A_LOAD, 32'h99BB33EE, OKAY, 66);
            end
        end

        // ---- AW/W ordering and backpressure ----
        axi_write(A_LOAD, 32'h00000010, 4'hF, 0, 3, 3, OKAY);
        rd(A_LOAD, 32'h00000010, OKAY, 70);
        axi_write(A_LOAD, 32'h00000020, 4'hF, 3, 0, 0, OKAY);
        rd(A_LOAD, 32'h00000020, OKAY, 71);
        axi_write(A_LOAD, 32'h00000030, 4'hF, 1, 0, -1, OKAY);
        rd(A_LOAD, 32'h00000030, OKAY, 72);

        // ---- Throughput: one per 2 cycles per direction ----
        axi_write(A_LOAD, 32'h00000040, 4'hF, 0, 0, -1, OKAY);
        c = wr_edge;
        axi_write(A_LOAD, 32'h00000050, 4'hF, 0, 0, -1, OKAY);
        check(wr_edge == c + 2, 73);
        axi_read(A_LOAD, -1, OKAY);
        c = rd_edge;
        axi_read(A_LOAD, -1, OKAY);
        check(rd_edge == c + 2, 74);
        check_eq(rd_data, 32'h00000050, 75);
        axi_read(A_LOAD, 4, OKAY);
        check_eq(rd_data, 32'h00000050, 76);

        // ---- Read and write on the same edge: read returns old value ----
        awvalid = 1'b1;
        awaddr  = ad(A_LOAD);
        wvalid  = 1'b1;
        wdata   = 32'h00000060;
        wstrb   = 4'hF;
        arvalid = 1'b1;
        araddr  = ad(A_LOAD);
        check(awready && wready && arready, 80);
        step;
        awvalid = 1'b0;
        wvalid  = 1'b0;
        arvalid = 1'b0;
        check(bvalid && rvalid, 81);
        check_eq(rdata, 32'h00000050, 82);
        check(bresp == OKAY && rresp == OKAY, 83);
        bready = 1'b1;
        rready = 1'b1;
        step;
        bready = 1'b0;
        rready = 1'b0;
        check(!bvalid && !rvalid, 84);
        rd(A_LOAD, 32'h00000060, OKAY, 85);

        // ---- One-shot, LOAD = 5: irq exactly after E+5 ----
        wr(A_LOAD, 32'd5, OKAY);
        wr(A_CTRL, 32'h00000003, OKAY);
        e = wr_edge;
        while (cyc < e + 8) begin
            check(irq == ((cyc - e) >= 5), 90);
            step;
        end
        wr(A_STATUS, 32'h00000001, OKAY);
        check(!irq, 91);
        rd(A_STATUS, 32'd0, OKAY, 92);
        rd(A_CTRL, 32'h00000002, OKAY, 93);
        rd(A_COUNT, 32'd0, OKAY, 94);

        // ---- One-shot, LOAD = 10: COUNT values ----
        wr(A_LOAD, 32'd10, OKAY);
        wr(A_CTRL, 32'h00000003, OKAY);
        e = wr_edge;
        axi_read(A_COUNT, 0, OKAY);
        check_eq(rd_data, cnt_after(32'd10, e, rd_edge - 1, 1'b0), 95);
        axi_read(A_COUNT, 3, OKAY);
        check_eq(rd_data, cnt_after(32'd10, e, rd_edge - 1, 1'b0), 96);
        wait_until(e + 12);
        check(irq, 97);
        rd(A_COUNT, 32'd0, OKAY, 98);

        // ---- Read stalled across an expiry: rdata holds ----
        wr(A_STATUS, 32'h00000001, OKAY);
        wr(A_CTRL, 32'h00000003, OKAY);
        e = wr_edge;
        axi_read(A_STATUS, 15, OKAY);
        check_eq(rd_data, 32'd0, 99);
        check(irq, 100);

        // ---- Periodic, LOAD = 4 ----
        wr(A_STATUS, 32'h00000001, OKAY);
        wr(A_LOAD, 32'd4, OKAY);
        wr(A_CTRL, 32'h00000007, OKAY);
        e = wr_edge;
        check(!irq, 110);
        wait_irq(e + 20);
        check_eq(cyc, e + 4, 111);
        axi_read(A_COUNT, 0, OKAY);
        check_eq(rd_data, cnt_after(32'd4, e, rd_edge - 1, 1'b1), 112);
        axi_read(A_COUNT, 2, OKAY);
        check_eq(rd_data, cnt_after(32'd4, e, rd_edge - 1, 1'b1), 113);
        axi_read(A_COUNT, 1, OKAY);
        check_eq(rd_data, cnt_after(32'd4, e, rd_edge - 1, 1'b1), 114);
        rd(A_CTRL, 32'h00000007, OKAY, 115);

        // STATUS clear off an end edge: irq drops, rises at next end edge
        while (((cyc + 1 - e) % 4) != 2) step;
        wr(A_STATUS, 32'h00000001, OKAY);
        c = wr_edge;
        check(((c - e) % 4) == 2, 116);
        check(!irq, 117);
        wait_irq(c + 20);
        check_eq(cyc, c + 2, 118);

        // STATUS clear on an end edge: EXPIRED stays set
        while (((cyc + 1 - e) % 4) != 0) step;
        wr(A_STATUS, 32'h00000001, OKAY);
        check(((wr_edge - e) % 4) == 0, 119);
        check(irq, 120);
        rd(A_STATUS, 32'd1, OKAY, 121);

        // IE masks irq only; IE=1 with EXPIRED=1 raises irq; restart with new mode
        wr(A_CTRL, 32'h00000005, OKAY);
        check(!irq, 122);
        rd(A_STATUS, 32'd1, OKAY, 123);
        wr(A_CTRL, 32'h00000007, OKAY);
        check(irq, 124);
        wr(A_CTRL, 32'h00000003, OKAY);
        e = wr_edge;
        wait_until(e + 10);
        rd(A_CTRL, 32'h00000002, OKAY, 125);
        rd(A_COUNT, 32'd0, OKAY, 126);

        // ---- CTRL EN=0 on a periodic end edge ----
        wr(A_STATUS, 32'h00000001, OKAY);
        wr(A_LOAD, 32'd6, OKAY);
        wr(A_CTRL, 32'h00000007, OKAY);
        e = wr_edge;
        wait_until(e + 5);
        wr(A_CTRL, 32'h00000006, OKAY);
        check_eq(wr_edge, e + 6, 130);
        check(irq, 131);
        rd(A_CTRL, 32'h00000006, OKAY, 132);
        rd(A_COUNT, 32'd6, OKAY, 133);
        rd(A_STATUS, 32'd1, OKAY, 134);
        repeat (5) step;
        rd(A_COUNT, 32'd6, OKAY, 135);

        // ---- CTRL EN=0 on a one-shot end edge ----
        wr(A_STATUS, 32'h00000001, OKAY);
        wr(A_CTRL, 32'h00000003, OKAY);
        e = wr_edge;
        wait_until(e + 5);
        wr(A_CTRL, 32'h00000002, OKAY);
        check_eq(wr_edge, e + 6, 140);
        rd(A_COUNT, 32'd0, OKAY, 141);
        rd(A_CTRL, 32'h00000002, OKAY, 142);
        rd(A_STATUS, 32'd1, OKAY, 143);
        check(irq, 144);

        // ---- CTRL EN=1 on a one-shot end edge: restart, EXPIRED set ----
        wr(A_STATUS, 32'h00000001, OKAY);
        wr(A_CTRL, 32'h00000003, OKAY);
        e = wr_edge;
        wait_until(e + 5);
        wr(A_CTRL, 32'h00000003, OKAY);
        c = wr_edge;
        check_eq(c, e + 6, 150);
        check(irq, 151);
        rd(A_CTRL, 32'h00000003, OKAY, 152);
        wr(A_STATUS, 32'h00000001, OKAY);
        check(wr_edge < c + 6, 153);
        check(!irq, 154);
        wait_irq(c + 20);
        check_eq(cyc, c + 6, 155);

        // ---- LOAD write on a periodic end edge: reload uses old LOAD ----
        wr(A_STATUS, 32'h00000001, OKAY);
        wr(A_LOAD, 32'd5, OKAY);
        wr(A_CTRL, 32'h00000007, OKAY);
        e = wr_edge;
        wait_until(e + 4);
        wr(A_LOAD, 32'd9, OKAY);
        c = wr_edge;
        check_eq(c, e + 5, 160);
        axi_read(A_COUNT, 0, OKAY);
        check_eq(rd_data, cnt_after(32'd5, c, rd_edge - 1, 1'b1), 161);
        wait_until(c + 5);
        axi_read(A_COUNT, 0, OKAY);
        check_eq(rd_edge, c + 6, 162);
        check_eq(rd_data, 32'd9, 163);
        wr(A_CTRL, 32'd0, OKAY);

        // ---- Stop mid-count: stop edge decrements, then COUNT holds ----
        wr(A_STATUS, 32'h00000001, OKAY);
        wr(A_LOAD, 32'd20, OKAY);
        wr(A_CTRL, 32'h00000003, OKAY);
        e = wr_edge;
        wait_until(e + 4);
        wr(A_CTRL, 32'h00000002, OKAY);
        c = wr_edge;
        check_eq(c, e + 5, 170);
        v = 32'd20 - $unsigned(c - e);
        rd(A_COUNT, v, OKAY, 171);
        repeat (3) step;
        rd(A_COUNT, v, OKAY, 172);
        rd(A_CTRL, 32'h00000002, OKAY, 173);
        wr(A_CTRL, 32'h00000002, OKAY);
        rd(A_COUNT, v, OKAY, 174);
        rd(A_STATUS, 32'd0, OKAY, 175);
        check(!irq, 176);

        // ---- LOAD = 0, periodic: ends on every edge ----
        wr(A_LOAD, 32'd0, OKAY);
        wr(A_CTRL, 32'h00000007, OKAY);
        check(irq, 180);
        rd(A_COUNT, 32'd0, OKAY, 181);
        wr(A_STATUS, 32'h00000001, OKAY);
        rd(A_STATUS, 32'd1, OKAY, 182);
        rd(A_CTRL, 32'h00000007, OKAY, 183);
        wr(A_CTRL, 32'd0, OKAY);
        check(!irq, 184);
        rd(A_CTRL, 32'd0, OKAY, 185);
        rd(A_COUNT, 32'd0, OKAY, 186);

        // ---- LOAD = 0, one-shot: ends on E+1, EN cleared ----
        wr(A_STATUS, 32'h00000001, OKAY);
        wr(A_CTRL, 32'h00000003, OKAY);
        check(irq, 190);
        rd(A_CTRL, 32'h00000002, OKAY, 191);
        rd(A_COUNT, 32'd0, OKAY, 192);

        // ---- Full 32-bit LOAD ----
        wr(A_STATUS, 32'h00000001, OKAY);
        wr(A_LOAD, 32'hFFFFFFFF, OKAY);
        wr(A_CTRL, 32'h00000001, OKAY);
        e = wr_edge;
        axi_read(A_COUNT, 0, OKAY);
        check_eq(rd_data, cnt_after(32'hFFFFFFFF, e, rd_edge - 1, 1'b0), 200);
        wr(A_CTRL, 32'd0, OKAY);
        c = wr_edge;
        v = 32'hFFFFFFFF - $unsigned(c - e);
        rd(A_COUNT, v, OKAY, 201);
        rd(A_LOAD, 32'hFFFFFFFF, OKAY, 202);
        check(!irq, 203);

        // ---- Reset during traffic ----
        wr(A_STATUS, 32'h00000001, OKAY);
        wr(A_LOAD, 32'd2, OKAY);
        wr(A_CTRL, 32'h00000003, OKAY);
        e = wr_edge;
        wait_until(e + 3);
        check(irq, 210);
        awvalid = 1'b1;
        awaddr  = ad(A_LOAD);
        check(awready, 211);
        step;
        awvalid = 1'b0;
        check(!awready && wready && !bvalid, 212);
        arvalid = 1'b1;
        araddr  = ad(A_CTRL);
        check(arready, 213);
        step;
        arvalid = 1'b0;
        check(rvalid, 214);
        aresetn = 1'b0;
        step;
        aresetn = 1'b1;
        check(!bvalid && !rvalid && !irq, 215);
        check(awready && wready && arready, 216);
        rd(A_CTRL,   32'd0, OKAY, 217);
        rd(A_LOAD,   32'd0, OKAY, 218);
        rd(A_COUNT,  32'd0, OKAY, 219);
        rd(A_STATUS, 32'd0, OKAY, 220);
        wr(A_LOAD, 32'h00001234, OKAY);
        rd(A_LOAD, 32'h00001234, OKAY, 221);

        done = 1'b1;
    end
endmodule

// Top: two DUT widths, one verdict line.
module tb_axil_timer;
    reg clk = 1'b0;
    always #5 clk = ~clk;

    wire        done4;
    wire        done6;
    wire [31:0] p4;
    wire [31:0] f4;
    wire [31:0] p6;
    wire [31:0] f6;

    axil_timer_tb_core #(.AW(4)) u_aw4 (.clk(clk), .done(done4), .n_pass(p4), .n_fail(f4));
    axil_timer_tb_core #(.AW(6)) u_aw6 (.clk(clk), .done(done6), .n_pass(p6), .n_fail(f6));

    reg [8*64-1:0] nonce;
    integer        t;
    reg            timeout;

    initial begin
        nonce = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = {(8*64){1'b0}};
        end
        timeout = 1'b0;
        t = 0;
        while (!(done4 && done6) && t < 100000) begin
            @(posedge clk);
            t = t + 1;
        end
        if (!(done4 && done6)) begin
            timeout = 1'b1;
            $error("testbench timeout: done4=%0d done6=%0d", done4, done6);
        end
        #2;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, p4 + p6, f4 + f6 + {31'd0, timeout});
        $finish;
    end
endmodule
